package com.hotel.booking;
import com.hotel.booking.config.DatabaseInitializer;import com.hotel.booking.service.*;import com.hotel.booking.model.*;import java.util.*;import java.math.BigDecimal;import java.time.LocalDate;
public class Main {
 private static final Scanner sc=new Scanner(System.in);private static final CustomerService customers=new CustomerService();private static final RoomService rooms=new RoomService();private static final BookingService bookings=new BookingService();
 public static void main(String[] args){try{DatabaseInitializer.initialize();System.out.println("\n=== HOTEL ROOM BOOKING BACKEND ===\nDatabase initialized successfully.\n");}catch(Exception e){System.out.println("Database setup failed: "+e.getMessage());System.out.println("Check MySQL is running and credentials in application.properties are correct.");return;}while(true){System.out.println("\n1 Add customer  2 List customers  3 Search customer\n4 Add room      5 List rooms     6 Available rooms\n7 Book room     8 List bookings  9 Cancel booking\n0 Exit");System.out.print("Choose: ");String choice=sc.nextLine().trim();try{switch(choice){case "1"->addCustomer();case "2"->customers.all().forEach(System.out::println);case "3"->searchCustomer();case "4"->addRoom();case "5"->rooms.all().forEach(System.out::println);case "6"->rooms.available().forEach(System.out::println);case "7"->bookRoom();case "8"->bookings.all().forEach(System.out::println);case "9"->cancelBooking();case "0"->{System.out.println("Goodbye!");return;}default->System.out.println("Choose a valid menu option.");}}catch(Exception e){System.out.println("Operation failed: "+e.getMessage());}}}
 private static void addCustomer()throws Exception{System.out.print("Customer name: ");String n=sc.nextLine();System.out.print("Phone: ");String p=sc.nextLine();System.out.print("Email (optional): ");String e=sc.nextLine();System.out.println("Saved: "+customers.add(n,p,e));}
 private static void searchCustomer()throws Exception{System.out.print("Name or phone to search: ");customers.search(sc.nextLine()).forEach(System.out::println);}
 private static void addRoom()throws Exception{System.out.print("Room number: ");String n=sc.nextLine();System.out.print("Room type (Single/Double/Deluxe): ");String t=sc.nextLine();System.out.print("Price per night: ");BigDecimal p=new BigDecimal(sc.nextLine());System.out.println("Saved: "+rooms.add(n,t,p));}
 private static void bookRoom()throws Exception{System.out.print("Customer ID: ");int c=Integer.parseInt(sc.nextLine());System.out.print("Room ID: ");int r=Integer.parseInt(sc.nextLine());System.out.print("Check-in (YYYY-MM-DD): ");LocalDate in=LocalDate.parse(sc.nextLine());System.out.print("Check-out (YYYY-MM-DD): ");LocalDate out=LocalDate.parse(sc.nextLine());System.out.println("Booking saved: "+bookings.book(c,r,in,out));}
 private static void cancelBooking()throws Exception{System.out.print("Booking ID: ");int id=Integer.parseInt(sc.nextLine());System.out.println(bookings.cancel(id)?"Booking cancelled.":"Booking not found or already cancelled.");}
}
